def find_topmost_carpet(n, carpets, point):
    """
    Finds the topmost carpet covering a given point on the coordinate plane.

    Args:
        n (int): The total number of carpets.
        carpets (list of tuples): A list containing n tuples, each representing a carpet's information.
                                  Each tuple contains four integers (a, b, g, k) where (a, b) is the
                                  coordinates of the bottom-left corner of the carpet and (g, k) are
                                  the lengths of the carpet along the x and y axis respectively.
        point (tuple): A tuple containing two integers (x, y), the coordinates of the point to check.

    Returns:
        int: The number of the topmost carpet covering the point (x, y), or -1 if no carpet covers it.
    """
    # Validate inputs
    try:
        if not isinstance(n, int) or n < 0:
            return -1
        if not isinstance(carpets, list) or len(carpets) != n:
            return -1
        if not isinstance(point, tuple) or len(point) != 2:
            return -1
        x, y = point
        if not (isinstance(x, int) and isinstance(y, int)):
            return -1
    except Exception:
        return -1

    # Iterate from topmost (last) to bottom
    for idx in range(n - 1, -1, -1):
        try:
            a, b, g, k = carpets[idx]
            if not all(isinstance(v, int) for v in (a, b, g, k)):
                continue
            if a <= x <= a + g and b <= y <= b + k:
                return idx + 1  # 1-based index
        except Exception:
            continue

    return -1

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string is split into K+1 contiguous
    substrings, each interpreted as an integer, and the product of these integers
    is computed. The function handles invalid inputs by raising appropriate
    exceptions and returns 0 when the product cannot be defined (e.g., K > N-1).
    """
    # Input validation
    if not isinstance(num_str, str):
        raise TypeError("num_str must be a string")
    if not isinstance(N, int) or not isinstance(K, int):
        raise TypeError("N and K must be integers")
    if len(num_str) != N:
        raise ValueError("Length of num_str does not match N")
    if N <= 0:
        return 0
    if K < 0:
        raise ValueError("K must be non‑negative")
    if K == 0:
        return int(num_str)
    if K > N - 1:
        return 0

    # Pre‑compute integer values for all substrings to avoid repeated conversions
    substr_val = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + int(num_str[j - 1])
            substr_val[i][j] = val

    # dp[i][k] = maximum product for the first i digits with k multiplications
    dp = [[None] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplications, product is the integer represented by the prefix
    for i in range(1, N + 1):
        dp[i][0] = substr_val[0][i]

    # Fill DP table
    for k in range(1, K + 1):
        for i in range(k + 1, N + 1):  # at least k+1 digits needed for k multiplications
            best = None
            for j in range(k, i):  # split point: first j digits with k-1 multiplications
                if dp[j][k - 1] is not None:
                    prod = dp[j][k - 1] * substr_val[j][i]
                    if best is None or prod > best:
                        best = prod
            dp[i][k] = best

    result = dp[N][K]
    return result if result is not None else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    first_term = True
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''

        term = f"{sign}{coeff_str}{var_part}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded, original, message):
    # Validate lengths
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    reverse_mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o
        if o in reverse_mapping:
            if reverse_mapping[o] != e:
                return "Failed"
        else:
            reverse_mapping[o] = e
    # Now decode message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])
    return "".join(decoded_chars)

def generate_numbers(n, rules):
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    for r in rules:
        if not (isinstance(r, tuple) and len(r)==2):
            raise ValueError("Each rule must be a tuple of two integers")
        x, y = r
        if not (isinstance(x, int) and isinstance(y, int)):
            raise ValueError("Rule digits must be integers")
        if not (0 <= x <= 9 and 0 <= y <= 9):
            raise ValueError("Rule digits must be between 0 and 9")
    from collections import deque
    visited = set()
    queue = deque()
    visited.add(n)
    queue.append(n)
    while queue:
        cur = queue.popleft()
        s = str(cur)
        for i, ch in enumerate(s):
            digit = int(ch)
            for x, y in rules:
                if x == digit:
                    new_s = s[:i] + str(y) + s[i+1:]
                    new_num = int(new_s)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def max_herb_value(T: int, M: int, herbs):
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    This function solves a variation of the 0/1 knapsack problem where the goal is to maximize
    the total value of herbs picked without exceeding the time limit. Each herb can be picked
    at most once and has an associated time cost and value.

    Args:
    - T (int): The total time available for picking herbs.
    - M (int): The number of different herbs in the cave.
    - herbs (List[Tuple[int, int]]): A list of tuples, where each tuple contains two integers
      representing the time required to pick the herb and the herb's value, respectively.

    Returns:
    - int: The maximum total value of herbs that can be picked within the time limit.
    """
    try:
        # Basic validation of inputs
        if not isinstance(T, int) or not isinstance(M, int):
            raise ValueError("T and M must be integers")
        if T < 0 or M < 0:
            raise ValueError("T and M must be non-negative")
        if not isinstance(herbs, list):
            raise ValueError("herbs must be a list of tuples")
        if len(herbs) != M:
            raise ValueError("Length of herbs list must equal M")

        # Initialize DP array for 0/1 knapsack
        dp = [0] * (T + 1)

        for idx, herb in enumerate(herbs):
            if not (isinstance(herb, tuple) and len(herb) == 2):
                raise ValueError(f"Herb at index {idx} is not a valid (time, value) tuple")
            time_cost, value = herb
            if not isinstance(time_cost, int) or not isinstance(value, int):
                raise ValueError(f"Herb at index {idx} contains non-integer values")
            if time_cost < 0 or value < 0:
                raise ValueError(f"Herb at index {idx} has negative time or value")

            # Update DP array in reverse to avoid reuse of the same herb
            for t in range(T, time_cost - 1, -1):
                new_val = dp[t - time_cost] + value
                if new_val > dp[t]:
                    dp[t] = new_val

        # The answer is the maximum value achievable within the time limit
        return max(dp)
    except Exception:
        # In case of any unexpected error, return 0 as a safe fallback
        return 0

def min_remaining_space(V: int, n: int, volumes: list) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    This function uses a dynamic programming approach to determine the maximum volume that can be occupied
    in the box by any subset of the given items. It then returns the difference between the box's total capacity
    and this maximum occupied volume, which is the minimum remaining space.

    Args:
    - V (int): The total capacity of the box.
    - n (int): The number of items to consider for packing into the box.
    - volumes (List[int]): A list of the volumes of the n items.

    Returns:
    - int: The minimum remaining space in the box after fitting the items.
    """
    try:
        if not isinstance(V, int) or V < 0:
            raise ValueError("Box capacity V must be a non-negative integer.")
        if not isinstance(n, int) or n < 0:
            raise ValueError("Number of items n must be a non-negative integer.")
        if not isinstance(volumes, list):
            raise ValueError("volumes must be a list of integers.")
        if n != len(volumes):
            raise ValueError("Length of volumes list must match n.")
        # Ensure all volumes are integers
        for idx, vol in enumerate(volumes):
            if not isinstance(vol, int):
                raise ValueError(f"Volume at index {idx} is not an integer.")
        # Dynamic programming for subset sum up to V
        dp = [False] * (V + 1)
        dp[0] = True
        for vol in volumes:
            if vol < 0:
                # Skip negative volumes as they cannot contribute to packing
                continue
            for cap in range(V, vol - 1, -1):
                if dp[cap - vol]:
                    dp[cap] = True
        # Find the maximum achievable volume
        max_occupied = max(idx for idx, possible in enumerate(dp) if possible)
        return V - max_occupied
    except Exception as e:
        # Log the exception details if needed; for now, re-raise with a clear message
        raise RuntimeError(f"Error computing minimum remaining space: {e}") from e

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    if not heights:
        return 0

    n = len(heights)
    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Longest bitonic subsequence length
    max_lbs = 0
    for i in range(n):
        lbs = lis[i] + lds[i] - 1
        if lbs > max_lbs:
            max_lbs = lbs

    return n - max_lbs

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
    student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
    list: A list of tuples sorted according to the above rules.
    """
    # Validate input
    if student_scores is None:
        raise TypeError("student_scores cannot be None")
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")
    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple):
            raise TypeError(f"Item at index {idx} is not a tuple")
        if len(item) != 3:
            raise ValueError(f"Tuple at index {idx} does not contain exactly 3 elements")
        student_number, total_score, chinese_score = item
        if not isinstance(student_number, int):
            raise TypeError(f"Student number at index {idx} is not an int")
        if not isinstance(total_score, (int, float)):
            raise TypeError(f"Total score at index {idx} is not a number")
        if not isinstance(chinese_score, (int, float)):
            raise TypeError(f"Chinese score at index {idx} is not a number")

    # Perform sorting
    try:
        sorted_list = sorted(
            student_scores,
            key=lambda x: (-x[1], -x[2], x[0])
        )
    except Exception as e:
        raise RuntimeError(f"An error occurred during sorting: {e}")

    return sorted_list
